import { useState, useEffect } from 'react';

function ExampleComponent() {
  const [data, setData] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      setLoading(true);
      try {
        const response = await fetch('/api/data');
        const result = await response.json();
        setData(result);
      } catch (error) {
        console.error('Failed to fetch:', error);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  if (loading) return <p>Loading...</p>;
  return <div>{data}</div>;
}

function useCustomHook<T>(initialValue: T) {
  const [value, setValue] = useState<T>(initialValue);
  const [history, setHistory] = useState<T[]>([]);

  const update = (newValue: T) => {
    setValue(newValue);
    setHistory(prev => [...prev, newValue]);
  };

  const reset = () => {
    setValue(initialValue);
    setHistory([]);
  };

  return { value, history, update, reset };
}

// Usage in a component
function MyComponent() {
  const { value, history, update, reset } = useCustomHook('');
  return (
    <div>
      <input value={value} onChange={e => update(e.target.value)} />
      <button onClick={reset}>Reset</button>
      <ul>{history.map((h, i) => <li key={i}>{h}</li>)}</ul>
    </div>
  );
}
